203	  // out. Customers SSH in and run `claude` using their own subscription or API
204	  // key — no setup on our side, zero token cost to us. Installs run in the
205	  // background (nohup below) so the VM still reports ready quickly.
206	  if (addons.claudeCode !== false) {
207	    // Same steps the backfill (task #73) runs on existing servers — one source of
