212	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
213	  if (addons.malwareScanner)
214	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
215	  if (server.osTemplate.setupScript) {
216	    // Game images install as a bare `docker run -d` with no systemd unit, which
217	    // the game control panel (systemctl-based) can never see or manage — wrap it
218	    // in a generated unit so start/stop/restart/backup/logs actually work. See
219	    // wrapDockerGameService for the full story; a no-op for non-game templates.
220	    setup.push(wrapDockerGameService(server.osTemplate.setupScript, server.osTemplate.family));
221	  }
222	  // NxCloud: when this VM backs a managed Nextcloud instance, `provision` stashes
223	  // the per-instance install script here (admin creds injected). See worker/nxcloud.ts.
224	  if (server.__nxcloudSetup) setup.push(server.__nxcloudSetup);
