228	  // Every VM gets a swapfile. A small plan (the 2 GB Starter is the common one)
229	  // with ZERO swap OOM-kills under any spike — a container image build, a traffic
230	  // burst, a migrated app's first request — and the kernel kills a process with no
231	  // warning and nothing to fall back on. A RAM-sized swapfile (capped so it never
232	  // eats a small root disk) turns a hard kill into slow-but-alive. Idempotent:
233	  // skips if any swap is already on or /swapfile already exists.
234	  const swapScript = [
235	    "#!/bin/bash",
236	    "# Nxeon: ensure a swapfile exists as an OOM safety net on small-RAM VMs.",
237	    "if swapon --show=NAME --noheadings 2>/dev/null | grep -q .; then exit 0; fi",
238	    "[ -e /swapfile ] && exit 0",
239	    'MEM_MB=$(awk "/MemTotal/{print int(\\$2/1024)}" /proc/meminfo 2>/dev/null || echo 1024)',
240	    "SWAP_MB=$MEM_MB",
241	    '[ "$SWAP_MB" -lt 1024 ] && SWAP_MB=1024',
242	    '[ "$SWAP_MB" -gt 4096 ] && SWAP_MB=4096',
243	    "# Leave >2 GB free on / so the swapfile never fills the root disk.",
244	    'AVAIL_MB=$(df -Pm / | awk "NR==2{print \\$4}")',
245	    '[ -n "$AVAIL_MB" ] && [ "$AVAIL_MB" -lt $((SWAP_MB + 2048)) ] && SWAP_MB=$((AVAIL_MB - 2048))',
246	    '[ "$SWAP_MB" -lt 256 ] && exit 0',
247	    "fallocate -l ${SWAP_MB}M /swapfile 2>/dev/null || dd if=/dev/zero of=/swapfile bs=1M count=${SWAP_MB} 2>/dev/null || exit 0",
248	    "chmod 600 /swapfile",
249	    "mkswap /swapfile >/dev/null 2>&1 || exit 0",
250	    "swapon /swapfile 2>/dev/null || exit 0",
251	    "grep -q '^/swapfile ' /etc/fstab 2>/dev/null || echo '/swapfile none swap sw 0 0' >> /etc/fstab",
252	    "grep -q '^vm.swappiness' /etc/sysctl.conf 2>/dev/null || { echo 'vm.swappiness=10' >> /etc/sysctl.conf; sysctl -w vm.swappiness=10 >/dev/null 2>&1 || true; }",
253	  ].join("\n");
254	
255	  // A friendly first-login guide + MOTD banner pointing at the portal hub.
