337	/**
338	 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
339	 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
340	 *
341	 * If the archive listing cannot be read we do NOT silently fall back to the raw
342	 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
343	 * and a provision that fails is recoverable while a cross-tenant disclosure is
344	 * not. The job retries; an operator sees why.
345	 */
346	async function allocateFreshVmid(conn: any): Promise<number> {
347	  const candidate = await conn.nextVmid();
348	  const archived = await archivedVmids(conn);
349	
350	  // Ids already in use, so skipping forward cannot land on a live VM. Read
351	  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
352	  let taken = new Set<number>();
353	  try {
354	    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
355	    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
356	  } catch {
357	    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
358	    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
359	  }
360	
361	  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
362	  if (skipped.length > 0) {
363	    console.warn(
364	      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
365	        `from a previous server; allocated ${vmid} instead`
366	    );
367	  }
368	  return vmid;
369	}
