import { requireArea } from "@/lib/rbac";
import { getMonitorFeed } from "@/lib/monitor-feed";
import { LiveMonitorTerminal } from "@/components/admin/LiveMonitorTerminal";

export const dynamic = "force-dynamic";

/**
 * Platform-wide Live Ops monitor — one console view of every server the
 * platform runs (VPS, game servers, shared hosting): what's happening right
 * now (Job + HostingTask feed) and how loaded the fleet is (live node CPU/RAM
 * from Proxmox, worker-sampled disk + bandwidth per server). See
 * lib/monitor-feed.ts for exactly which numbers are live-per-request vs.
 * sampled-on-a-cadence, and what genuinely isn't collected yet.
 *
 * SSR renders the first paint from the same `getMonitorFeed()` the poll
 * endpoint (`/api/admin/monitor-feed`) calls, so there's no loading flash —
 * <LiveMonitorTerminal/> takes it as `initial` and polls from there.
 */
export default async function AdminMonitor() {
  await requireArea("fleet");
  const feed = await getMonitorFeed();

  return (
    <div>
      <div className="mb-6 flex items-baseline justify-between">
        <div>
          <h1 className="page-title">Live Ops</h1>
          <p className="mt-1 text-sm text-slate-400">
            Real-time console across every VPS, game server, and hosting account on the fleet.
          </p>
        </div>
      </div>
      <LiveMonitorTerminal initial={feed} />
    </div>
  );
}

