import { test } from "node:test";
import assert from "node:assert/strict";
import { GAME_FAMILIES } from "../lib/games.ts";
import { GAME_PORT } from "../lib/games.ts";
import {
  attemptsFor,
  retryCheck,
  gameFamilyForServer,
  gamePortForServer,
} from "../worker/provision-health.ts";

/* ------------------------------------------------------------------ *
 * GAME_PORT: every family must resolve to a real, sane port + protocol.
 * ------------------------------------------------------------------ */

test("GAME_PORT has an entry for every GAME_FAMILIES member", () => {
  for (const fam of GAME_FAMILIES) {
    assert.ok(GAME_PORT[fam], `missing GAME_PORT entry for ${fam}`);
  }
});

test("GAME_PORT entries are well-formed", () => {
  for (const [fam, entry] of Object.entries(GAME_PORT)) {
    assert.ok(Number.isInteger(entry.port), `${fam} port is not an integer`);
    assert.ok(entry.port > 0 && entry.port < 65536, `${fam} port ${entry.port} out of range`);
    assert.ok(entry.protocol === "tcp" || entry.protocol === "udp", `${fam} protocol invalid`);
  }
});

/* ------------------------------------------------------------------ *
 * attemptsFor: pure retry-count math.
 * ------------------------------------------------------------------ */

test("attemptsFor counts the first attempt plus every full interval that fits", () => {
  assert.equal(attemptsFor(0, 5_000), 1);
  assert.equal(attemptsFor(4_999, 5_000), 1);
  assert.equal(attemptsFor(5_000, 5_000), 2);
  assert.equal(attemptsFor(29_000, 5_000), 6);
  assert.equal(attemptsFor(300_000, 10_000), 31);
});

test("attemptsFor never returns fewer than 1, even for degenerate input", () => {
  assert.equal(attemptsFor(-1, 5_000), 1);
  assert.equal(attemptsFor(60_000, 0), 1);
  assert.equal(attemptsFor(60_000, -5), 1);
  assert.equal(attemptsFor(NaN, 5_000), 1);
});

